package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId string // PIC X(5) @0 len=5
	OrStat string // PIC X(1) @5 len=1
	OrQty int64 // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsTotal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsGrand decimal.Decimal // PIC 9(10)V99 len=12 = 0
var WsNewCount int64 // PIC 99 len=2 = 0
var WsShipCount int64 // PIC 99 len=2 = 0
var WsCancelCount int64 // PIC 99 len=2 = 0
var WsInvalid int64 // PIC 99 len=2 = 0
var WsBadQty int64 // PIC 99 len=2 = 0
var WsQtyEd string // PIC ZZ9 len=3
var WsPriceEd string // PIC Z,ZZ9.99 len=8
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var curRec OrderRec
var allLines []string
var recIdx int

func inputDone() bool { return WsEofFlag == "Y" }

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx == -1 {
		intPic = pic
		fracPic = ""
	} else {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	}
	intSlots := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for i := 0; i < len(fracPic); i++ {
		if fracPic[i] == 'Z' || fracPic[i] == '9' {
			fracSlots++
		}
	}
	abs := val
	if val.IsNegative() {
		abs = val.Neg()
	}
	scaled := abs.Shift(int32(fracSlots)).Truncate(0)
	iv := scaled.IntPart()
	var powFrac int64 = 1
	for i := 0; i < fracSlots; i++ {
		powFrac *= 10
	}
	var powInt int64 = 1
	for i := 0; i < intSlots; i++ {
		powInt *= 10
	}
	var intPart, fracPart int64
	if fracSlots > 0 {
		fracPart = iv % powFrac
		intPart = iv / powFrac
	} else {
		intPart = iv
		fracPart = 0
	}
	if powInt != 0 {
		intPart = intPart % powInt
	}
	if intPart < 0 {
		intPart = -intPart
	}
	if fracPart < 0 {
		fracPart = -fracPart
	}
	sInt := fmt.Sprintf("%0*d", intSlots, intPart)
	sFrac := ""
	if fracSlots > 0 {
		sFrac = fmt.Sprintf("%0*d", fracSlots, fracPart)
	}
	var out []byte
	out = make([]byte, 0, len(pic))
	idxInt := 0
	idxFrac := 0
	significant := false
	afterDot := false
	for i := 0; i < len(pic); i++ {
		ch := pic[i]
		switch ch {
		case 'Z', '9':
			if !afterDot {
				d := byte('0')
				if idxInt < len(sInt) {
					d = sInt[idxInt]
				}
				idxInt++
				if ch == 'Z' && !significant && d == '0' {
					out = append(out, ' ')
				} else {
					out = append(out, d)
					significant = true
				}
			} else {
				d := byte('0')
				if idxFrac < len(sFrac) {
					d = sFrac[idxFrac]
				}
				idxFrac++
				out = append(out, d)
			}
		case ',':
			if significant {
				out = append(out, ',')
			} else {
				out = append(out, ' ')
			}
		case '.':
			out = append(out, '.')
			afterDot = true
		default:
			out = append(out, ch)
		}
	}
	return string(out)
}

func formatCount(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func maskTotal(v decimal.Decimal) decimal.Decimal {
	neg := v.IsNegative()
	abs := v
	if neg {
		abs = v.Neg()
	}
	scaled := abs.Shift(2).Truncate(0)
	iv := scaled.IntPart()
	iv = iv % 10000000000
	res := decimal.New(iv, -2)
	if neg {
		res = res.Neg()
	}
	return res
}

func maskGrand(v decimal.Decimal) decimal.Decimal {
	neg := v.IsNegative()
	abs := v
	if neg {
		abs = v.Neg()
	}
	scaled := abs.Shift(2).Truncate(0)
	iv := scaled.IntPart()
	iv = iv % 1000000000000
	res := decimal.New(iv, -2)
	if neg {
		res = res.Neg()
	}
	return res
}

func parseDigits(b []byte) int64 {
	var sb strings.Builder
	for _, c := range b {
		if c >= '0' && c <= '9' {
			sb.WriteByte(c)
		} else if c == ' ' {
			sb.WriteByte('0')
		} else {
			sb.WriteByte('0')
		}
	}
	s := sb.String()
	// strip leading zeros to avoid overflow? fits
	if s == "" {
		return 0
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func parseRecord(line string) OrderRec {
	b := []byte(line)
	if len(b) < 15 {
		nb := make([]byte, 15)
		copy(nb, b)
		for i := len(b); i < 15; i++ {
			nb[i] = ' '
		}
		b = nb
	} else if len(b) > 15 {
		b = b[:15]
	}
	var r OrderRec
	r.OrId = string(b[0:5])
	r.OrStat = string(b[5:6])
	r.OrQty = parseDigits(b[6:9])
	n := parseDigits(b[9:15])
	r.OrPrice = decimal.New(n, -2)
	return r
}

func MainPara() {
	// OPEN INPUT ORDER-FILE
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// empty file treated as no records? COBOL would error, but if missing treat as empty only if not exist?
		// Follow spec: errors go to stderr with non-zero exit.
		// If file does not exist, treat as empty to allow? Strict: report error.
		// Check: if file missing, exit with error.
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	s := string(data)
	parts := strings.Split(s, "\n")
	// drop trailing empty caused by final newline
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		// This empty comes from trailing newline; remove it.
		// But need to distinguish file "" (one part "") vs "a\n" (two parts). Empty file should give 0 records.
		parts = parts[:len(parts)-1]
	}
	allLines = make([]string, 0, len(parts))
	for _, p := range parts {
		if len(p) > 0 && p[len(p)-1] == '\r' {
			p = p[:len(p)-1]
		}
		allLines = append(allLines, p)
	}
	recIdx = 0
	ReadPara()
	for !inputDone() {
		ProcessPara()
	}
	// CLOSE ORDER-FILE (no-op)
	SummaryPara()
}

func ReadPara() {
	if recIdx >= len(allLines) {
		WsEofFlag = "Y"
		return
	}
	curRec = parseRecord(allLines[recIdx])
	recIdx++
}

func ProcessPara() {
	WsTotal = decimal.New(0, 0)
	orQty := curRec.OrQty
	orStat := curRec.OrStat
	if orQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		os.Stdout.WriteString(curRec.OrId + " BAD QTY" + "\n")
	} weal0:
	if false {
		goto weal0
	}
	// EVALUATE TRUE in order
	if orQty == 0 {
		// already handled
	} else if orStat == "N" {
		tmp := decimal.NewFromInt(orQty).Mul(curRec.OrPrice).Truncate(2)
		WsTotal = maskTotal(tmp)
		WsNewCount = (WsNewCount + 1) % 100
		ShowPara()
	} else if orStat == "S" {
		rate := decimal.New(105, -2)
		tmp := decimal.NewFromInt(orQty).Mul(curRec.OrPrice).Mul(rate).Round(2)
		WsTotal = maskTotal(tmp)
		WsShipCount = (WsShipCount + 1) % 100
		ShowPara()
	} else if orStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		ShowPara()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		os.Stdout.WriteString(curRec.OrId+" BAD STATUS "+orStat+"\n")
	}
	WsGrand = maskGrand(WsGrand.Add(WsTotal))
	ReadPara()
}

func ShowPara() {
	WsQtyEd = formatEdited(decimal.New(curRec.OrQty, 0), "ZZ9")
	WsPriceEd = formatEdited(curRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	os.Stdout.WriteString(curRec.OrId + " " + curRec.OrStat + " " + WsQtyEd + " " + WsPriceEd + " " + WsTotalEd + "\n")
}

func SummaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	os.Stdout.WriteString("NEW: " + formatCount(WsNewCount) + " SHIPPED: " + formatCount(WsShipCount) + " CANCELLED: " + formatCount(WsCancelCount) + "\n")
	os.Stdout.WriteString("INVALID: " + formatCount(WsInvalid) + " BAD QTY: " + formatCount(WsBadQty) + "\n")
	os.Stdout.WriteString("GRAND TOTAL: " + WsGrandEd + "\n")
}

func main() {
	WsEofFlag = "N"
	WsTotal = decimal.New(0, 0)
	WsGrand = decimal.New(0, 0)
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0
	MainPara()
}

